_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _validate_base(base):
    if not isinstance(base, int) or isinstance(base, bool) or not 2 <= base <= 36:
        raise ValueError("base must be between 2 and 36")


def to_base(number, base):
    _validate_base(base)

    if number == 0:
        return "0"

    sign = "-" if number < 0 else ""
    number = abs(number)
    digits = []
    while number:
        number, remainder = divmod(number, base)
        digits.append(_DIGITS[remainder])
    return sign + "".join(reversed(digits))


def from_base(text, base):
    _validate_base(base)
    if not isinstance(text, str) or not text:
        raise ValueError("text must contain at least one digit")

    sign = 1
    if text[0] == "-":
        sign = -1
        text = text[1:]
    if not text:
        raise ValueError("text must contain at least one digit")

    value = 0
    for character in text:
        digit = _DIGITS.find(character.lower())
        if digit < 0 or digit >= base:
            raise ValueError("invalid digit for base")
        value = value * base + digit
    return sign * value
